// This endpoint spends money every time it answers, so everything here runs BEFORE the model does.
//
// The Webhook node already rejected anyone without the shared secret (Header Auth, so the secret lives in
// n8n's encrypted credential store rather than in this workflow). What is left to decide is whether THIS
// request is worth paying for.
const req = $input.first().json;
const body = req.body ?? {};
const headers = req.headers ?? {};

const question = String(body.question ?? '').replace(/\s+/g, ' ').trim();

if (!question) {
  throw new Error('question is required');
}
// A cap, not a truncation: a 50 KB "question" is either a mistake or someone using your budget as a
// pastebin, and silently answering the first 500 characters of it teaches nobody anything.
if (question.length > 500) {
  throw new Error(`question is ${question.length} characters, the limit is 500`);
}

// Who to count this against. Prefer a caller-supplied identity (your own app knows which customer is
// asking); fall back to the forwarded client address. Neither is trustworthy on its own — the point of the
// counter is to cap accidental and casual abuse, and the shared secret is what keeps strangers out.
const sender =
  String(body.sender ?? '').trim() ||
  String(headers['x-forwarded-for'] ?? '').split(',')[0].trim() ||
  'anonymous';

// A FIXED-WINDOW counter: the key carries the minute, so each minute starts at zero.
//
// Why not one key per sender with a TTL: n8n's Redis node calls EXPIRE on *every* increment, which keeps
// pushing the expiry out, so a sender under continuous traffic would never get a fresh window and would
// stay blocked until they paused. Bucketing by minute makes that harmless — the old bucket just expires
// unused.
const minute = Math.floor(Date.now() / 60000);

return [
  {
    json: {
      question,
      sender,
      rateKey: `faq:rl:${sender}:${minute}`,
      limit: 20,
      askedAt: new Date().toISOString(),
    },
  },
];

// The Redis node returns { "<the key>": <new count> }, and the key is built at runtime, so the count cannot
// be read by name. Object.values() is the robust way, and re-attaching the question keeps everything after
// this node readable — the Redis node drops the incoming fields.
const counted = Object.values($input.first().json)[0];
const count = Number(counted ?? 0);
const asked = $('Check the question').first().json;

return [
  {
    json: {
      ...asked,
      count,
      withinLimit: count <= asked.limit,
      // Seconds until this minute's bucket rolls over — what a 429 should tell the caller to wait.
      retryAfter: 60 - Math.floor((Date.now() % 60000) / 1000),
    },
  },
];

// The model was told to answer KHONG_BIET ("I do not know") when the FAQ does not cover the question. That
// sentinel is the whole guardrail: it turns "the model is unsure" from a sentence a human has to judge into
// a flag this workflow can act on.
//
// Without it, an FAQ bot's worst failure is confident invention — a made-up delivery fee is worse than no
// answer, because the customer believes it.
const text = String($input.first().json.text ?? '').trim();
const asked = $('Check the question').first().json;

const unsure = text === 'KHONG_BIET' || text.includes('KHONG_BIET') || text === '';

return [
  {
    json: {
      answered: !unsure,
      question: asked.question,
      answer: unsure
        ? 'Xin loi, cau hoi nay can nhan vien tra loi. Chung toi se lien he lai. / Sorry, this needs a person. We will get back to you.'
        : text,
      // So the business can see what the bot could not answer: those are the next FAQ entries to write.
      needsHuman: unsure,
      askedAt: asked.askedAt,
    },
  },
];
